update_rule.pseudocode:
G = signal.network_graph
active_edges = []
# Edge activation
for each edge (u, v) in G.edges:
  if Bernoulli(parameters.edge_activation_rate_daily) == 1:
    active_edges.append((u, v))
# Rewiring (degree-preserving at low rate)
for each node u in G.nodes:
  if Bernoulli(parameters.rewiring_rate) == 1:
    pick neighbor v uniformly
    pick candidate w from nodes with same group as u and not connected to u
    if such w exists:
      remove edge (u, v); add edge (u, w)
# Output active contacts
signal.active_contacts = active_edges

initialize counts: new_adopts = 0, dropouts = 0
# Influence accumulation per person
for each person i:
  active_adopting_neighbors = number of neighbors j where (i, j) in signal.active_contacts and adopted[j] == True
  social_infl = parameters.influence_weight_per_contact * active_adopting_neighbors
  if active_adopting_neighbors >= 2:
    social_infl *= (1.0 + parameters.reinforcement_synergy)
  exog = policy.exposure_vector[i]
  infl = parameters.baseline_adoption_exposure + social_infl + exog
  eff_threshold = threshold[i] - policy.threshold_reduction_vector[i]
  eff_threshold = max(0.0, min(1.0, eff_threshold))
  perceived = infl * susceptibility[i]
  # Adoption decision
  if adopted[i] == False:
    if (t - last_drop_day[i]) >= parameters.refractory_period_days:
      if perceived >= eff_threshold:
        adopted_next[i] = True
        last_adopted_day[i] = t
        satisfaction[i] += 1.0
        new_adopts += 1
      else:
        adopted_next[i] = False
    else:
      adopted_next[i] = False
  else:
    # Abandonment hazard
    hazard = parameters.abandonment_hazard_base * exp(-satisfaction[i])
    if parameters.adoption_is_absorbing == True:
      hazard = 0.0
    if Bernoulli(hazard) == 1:
      adopted_next[i] = False
      last_drop_day[i] = t
      dropouts += 1
    else:
      adopted_next[i] = True
  # Satisfaction update
  if active_adopting_neighbors > 0:
    satisfaction[i] = min(satisfaction[i] + 0.5, 10.0)
  else:
    satisfaction[i] = max(satisfaction[i] - parameters.satisfaction_decay_rate, 0.0)
# Commit updates
adopted = adopted_next
output state.person_adopted, event.new_adoptions = new_adopts, event.dropouts = dropouts, state.satisfaction
